:root {
  color-scheme: dark;
}

html,body {
  margin: 0;
  height: 100%;
  background: #0a0a0a;
}

body {
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #0a0a0a;
  color: #e5e7eb;
}

.card {
  width: 100%;
  max-width: 520px;
  background: #0b1020;
  border: 1px solid #1f2937;
  border-radius: 14px;
  padding: 18px;
  display: grid;
  gap: 14px;
}

.title {
  margin: 0;
  font-size: 18px;
  font-weight: 800;
}

.subtitle {
  margin: 0;
  color: #9ca3af;
  font-size: 12px;
}

.row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.likeBtn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border-radius: 999px;
  padding: 10px 14px;
  border: 1px solid #374151;
  background: #0a0f1e;
  color: #e5e7eb;
  font-weight: 800;
  cursor: pointer;
}

.likeBtn:hover {
  border-color: #4b5563;
}

.likeBtn.active {
  background: rgba(59,130,246,0.15);
  border-color: rgba(59,130,246,0.7);
  color: #dbeafe;
}

.icon {
  font-size: 16px;
  line-height: 1;
}

.label {
  font-size: 14px;
}

.count {
  min-width: 64px;
  text-align: center;
  background: #0a0f1e;
  border: 1px solid #1f2937;
  border-radius: 12px;
  padding: 10px 12px;
  font-weight: 900;
}

.hint {
  margin: 0;
  color: #9ca3af;
  font-size: 12px;
  line-height: 1.35;
}
